import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"8、【比】 坤下坎上","description":"子夏易傳 - 8、【比】 坤下坎上","frontmatter":{"title":"8、【比】 坤下坎上","description":"子夏易傳 - 8、【比】 坤下坎上"},"headers":[],"relativePath":"classics/zixia/010.md","filePath":"classics/zixia/010.md"}'),i={name:"classics/zixia/010.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_8、【比】-坤下坎上" tabindex="-1">8、【比】 坤下坎上 <a class="header-anchor" href="#_8、【比】-坤下坎上" aria-label="Permalink to “8、【比】 坤下坎上”">​</a></h1><p>卦辭：比，吉，原筮元永貞，無咎，不寧方來，後夫兇。</p><p>象曰：比，吉也。比，輔也。下順從也。原筮元永貞，無咎。以剛中也。不寧方來，上下應也。後夫兇，其道窮也。</p><p>子夏：眾畏險民，鹹其安也。輔其正而獲吉也。剛位於尊也。本其陽之德行，仁也。居中可以長正也。長正可以寧方也。筮而比之，亦何咎也，則不寧，輔而安矣。後夫道窮，雖求輔，兇也。</p><p>象曰：地上有水，比先王以建萬國，親諸侯。</p><p>子夏：地載水而澤也，水得地而安也。下得上而寧也，上得下而位也。故先王建萬國和親諸侯，然後天下安也。</p><p>初六，有孚，比之無咎。有孚，盈缶終來。有他吉。</p><p>象曰：比之初六，有他吉也。</p><p>子夏：眾各保其所居也。能初以求比，是以吉也。知乎幾，辨乎微，為天下首。比必自誠信盈於素分也。素分盈，則主恩及，而他吉來矣。</p><p>六二，比之自內，貞吉。</p><p>象曰：比之自內，不自失也。</p><p>子夏：為五內比，應而相合，承其私也。為眾所覩也。能自守中正，故保其吉也。</p><p>六三，比之匪人，</p><p>象曰：比之匪人，不亦傷乎。</p><p>子夏：不正，不能辨，其去就，而輔於上，無首也。可比非其人乎，不亦傷矣。</p><p>六四，外比之，貞吉。</p><p>象曰：外比於賢，以從上也。</p><p>子夏：比於尊，剛承上，輔賢，得正，吉也。</p><p>九五，顯比，王用三驅，失前禽，邑人不誡，吉。</p><p>象曰：顯比之，吉。位正中也。舍逆取順，失前禽也。邑人不誡，上使中也。</p><p>子夏：為天下王也，背之以來，皆吾人也。則可以安天下矣。獨守其中，而私其應，為眾所觀，非顯其私歟。疾其背，而愛其向也。則失其不來者矣。邑有家者也，私也，豈王者顯私也。偏其私，故邑人不誡，王所使之，然也。雖顯，其吉。正其位而尊也。</p><p>上六，比之無首，兇。</p><p>象曰：比之無首，無所終也。</p><p>子夏：無誠於附，道窮，而比，戮，斯及矣，何終哉。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
